474:         // nothing
475:     } else if (mpctx->stop_play == PT_QUIT) {
476:         reason = "Quit";
477:     } else if (mpctx->files_played) {
478:         if (mpctx->files_errored || mpctx->files_broken) {
479:             reason = "Some errors happened";
